/// <reference types="ws" />
/// <reference types="node" />
import { SignalingServerResponse, IceCandidate, MessageSources } from '@radixdlt/radix-connect-schemas';
import * as rxjs from 'rxjs';
import { Subject, BehaviorSubject, ReplaySubject } from 'rxjs';
import { Logger } from 'tslog';
import { ResultAsync } from 'neverthrow';
import IsomorphicWebSocket from 'isomorphic-ws';

type SignalingSubjectsType = ReturnType<typeof SignalingSubjects>;
declare const SignalingSubjects: () => {
    onMessageSubject: Subject<SignalingServerResponse>;
    onErrorSubject: Subject<Event>;
    statusSubject: BehaviorSubject<Status>;
    targetClientIdSubject: BehaviorSubject<string | undefined>;
};

type WebRtcSubjectsType = ReturnType<typeof WebRtcSubjects>;
declare const WebRtcSubjects: () => {
    onNegotiationNeededSubject: Subject<void>;
    onIceCandidateSubject: Subject<RTCIceCandidate>;
    iceCandidatesSubject: BehaviorSubject<IceCandidateMessage[]>;
    onRemoteIceCandidateSubject: Subject<RTCIceCandidate>;
    remoteIceCandidatesSubject: BehaviorSubject<RTCIceCandidate[]>;
    offerSubject: ReplaySubject<Pick<{
        requestId: string;
        targetClientId: string;
        encryptedPayload: string;
        method: "offer";
        payload: {
            sdp: string;
        };
        source?: "wallet" | "extension" | undefined;
        connectionId?: string | undefined;
    }, "payload" | "method" | "source">>;
    answerSubject: ReplaySubject<Pick<{
        requestId: string;
        targetClientId: string;
        encryptedPayload: string;
        method: "answer";
        payload: {
            sdp: string;
        };
        source?: "wallet" | "extension" | undefined;
        connectionId?: string | undefined;
    }, "payload" | "method" | "source">>;
    onRemoteAnswerSubject: Subject<void>;
    onSignalingStateChangeSubject: Subject<RTCSignalingState>;
    dataChannelStatusSubject: BehaviorSubject<"open" | "closed">;
    iceConnectionStateSubject: BehaviorSubject<RTCIceConnectionState | undefined>;
    onRemoteDescriptionSuccessSubject: BehaviorSubject<boolean>;
    onLocalDescriptionSuccessSubject: BehaviorSubject<boolean>;
    remoteAnswerSubject: BehaviorSubject<RTCSessionDescriptionInit | undefined>;
    peerConnectionStateSubject: BehaviorSubject<RTCPeerConnectionState | undefined>;
};

type WebSocket = typeof IsomorphicWebSocket;
declare const NodeWebSocket: () => WebSocket;

type AConstructorTypeOf<A, T> = new (args: A) => T;
type WebRTC = {
    RTCIceCandidate: AConstructorTypeOf<RTCIceCandidateInit, RTCIceCandidate>;
    RTCSessionDescription: AConstructorTypeOf<RTCSessionDescriptionInit, RTCSessionDescription>;
    RTCPeerConnection: AConstructorTypeOf<RTCConfiguration, RTCPeerConnection>;
};

type IceCandidateMessage = Pick<IceCandidate, 'method' | 'payload' | 'source'>;
type Message = Record<string, any>;
type Status = 'connecting' | 'connected' | 'disconnected' | 'disconnecting';
type MetaData = {
    packageType: 'metaData';
    chunkCount: number;
    hashOfMessage: string;
    messageId: string;
    messageByteCount: number;
};
type MessageChunk = {
    packageType: 'chunk';
    chunkIndex: number;
    chunkData: string;
    messageId: string;
};
type MessageConfirmation = {
    packageType: 'receiveMessageConfirmation';
    messageId: string;
};
declare const messageErrorReasons: {
    readonly notConnected: "notConnected";
    readonly failedToSendMessage: "failedToSendMessage";
    readonly failedToPrepareMessage: "failedToPrepareMessage";
    readonly timeout: "timeout";
};
type MessageErrorReasons = keyof typeof messageErrorReasons;
type ChunkedMessageReceiveMessageError = {
    packageType: 'receiveMessageError';
    messageId: string;
    error: MessageErrorReasons;
};
type MessageErrorTypes = ChunkedMessageReceiveMessageError;
type ChunkedMessageType = MetaData | MessageChunk | MessageConfirmation | MessageErrorTypes;
type TurnServer = {
    urls: string;
    username: string;
    credential: string;
};
type ConnectionConfig = {
    signalingServerBaseUrl: string;
    turnServers?: TurnServer[];
    iceTransportPolicy?: RTCIceTransportPolicy;
};

type ConnectorClientSubjects = ReturnType<typeof ConnectorClientSubjects>;
declare const ConnectorClientSubjects: () => {
    shouldConnectSubject: BehaviorSubject<boolean>;
    connected: BehaviorSubject<boolean>;
    connectionConfig: BehaviorSubject<ConnectionConfig | undefined>;
    triggerRestartSubject: Subject<void>;
    onDataChannelMessageSubject: Subject<ChunkedMessageType>;
    onMessage: Subject<Message>;
    sendMessageOverDataChannelSubject: Subject<string>;
};

type ConnectorClient = ReturnType<typeof ConnectorClient>;
declare const ConnectorClient: (input: {
    target: MessageSources;
    source: MessageSources;
    isInitiator: boolean;
    logger?: Logger<unknown>;
    createWebRtcSubjects?: () => WebRtcSubjectsType;
    createSignalingSubjects?: () => SignalingSubjectsType;
    subjects?: ConnectorClientSubjects;
    dependencies?: Partial<{
        WebRTC: WebRTC;
        WebSocket: WebSocket;
    }>;
    negotiationTimeout?: number;
}) => {
    connected$: rxjs.Observable<boolean>;
    connected: () => ResultAsync<boolean, Error>;
    setConnectionPassword: (password: Buffer) => ResultAsync<void, Error>;
    connectionPassword$: rxjs.Observable<Buffer | undefined>;
    setConnectionConfig: (config: ConnectionConfig) => void;
    generateConnectionPassword: () => ResultAsync<Buffer, Error>;
    connect: () => void;
    disconnect: () => void;
    shouldConnect$: rxjs.Observable<boolean>;
    restart: () => void;
    sendMessage: (message: Record<string, any>, options?: Partial<{
        messageEventCallback: (event: 'messageSent') => void;
        timeout: number;
    }> | undefined) => ResultAsync<undefined, {
        reason: MessageErrorReasons;
        jsError?: Error;
    }>;
    onMessage$: rxjs.Observable<Message>;
    destroy: () => void;
};

declare const createLogger: (minLevel: number) => Logger<unknown>;

export { type ConnectionConfig, ConnectorClient, ConnectorClientSubjects, NodeWebSocket, SignalingSubjects, type TurnServer, WebRtcSubjects, createLogger };
